const body = $json.body ?? $json;
const event = String(body.event ?? '').toLowerCase();
const data = body.data ?? body;
const key = data.key ?? {};
const remoteJid = String(key.remoteJid ?? data.remoteJid ?? '');
const message = data.message ?? {};
const text = message.conversation ?? message.extendedTextMessage?.text ?? message.imageMessage?.caption ?? '';
const instanceName = String(body.instance ?? data.instance ?? '');
if (!event.includes('messages') || key.fromMe || !remoteJid || !text || !instanceName) return [];
const patientPhone = remoteJid.replace(/@.*/, '').replace(/\D/g, '');
if (!patientPhone) return [];
return [{ json: { instanceName, patientPhone, patientMessage: String(text).trim() } }];

